class Solution:
    def hitBricks(self, grid: list[list[int]], hits: list[list[int]]) -> list[int]:
        m, n = len(grid), len(grid[0])

        # Directions for neighbors
        directions = [(1,0), (-1,0), (0,1), (0,-1)]

        # Union-Find (Disjoint Set Union) structure
        # We add one extra node for the "roof"
        parent = list(range(m*n + 1))
        size = [1] * (m*n + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                if size[rx] < size[ry]:
                    rx, ry = ry, rx
                parent[ry] = rx
                size[rx] += size[ry]

        def index(r, c):
            return r * n + c

        # Step 1: Mark bricks that will be hit as 0 in a copy grid
        copy_grid = [row[:] for row in grid]
        for r, c in hits:
            if copy_grid[r][c] == 1:
                copy_grid[r][c] = 0

        # Step 2: Build union-find for the grid after all hits
        # Connect top row bricks to the roof node (m*n)
        for c in range(n):
            if copy_grid[0][c] == 1:
                union(index(0,c), m*n)

        # Connect adjacent bricks in the copy_grid
        for r in range(1, m):
            for c in range(n):
                if copy_grid[r][c] == 1:
                    # connect with top neighbor if brick
                    if copy_grid[r-1][c] == 1:
                        union(index(r,c), index(r-1,c))
                    # connect with left neighbor if brick
                    if c > 0 and copy_grid[r][c-1] == 1:
                        union(index(r,c), index(r,c-1))

        # Step 3: Process hits in reverse order
        res = [0] * len(hits)
        for i in range(len(hits)-1, -1, -1):
            r, c = hits[i]
            # If there was no brick originally, nothing falls
            if grid[r][c] == 0:
                continue

            # Before adding back the brick, record the size of roof component
            prev_roof_size = size[find(m*n)]

            # Add the brick back
            copy_grid[r][c] = 1

            # If brick is in top row, connect to roof
            if r == 0:
                union(index(r,c), m*n)

            # Connect with neighbors if they are bricks
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and copy_grid[nr][nc] == 1:
                    union(index(r,c), index(nr,nc))

            # After union, get new roof size
            new_roof_size = size[find(m*n)]

            # Number of bricks that fell is the increase in roof size minus 1 (the brick we just added)
            fallen = max(0, new_roof_size - prev_roof_size - 1)
            res[i] = fallen

        return res

